      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-2: #f8fafc;
      --text: #102033;
      --muted: #5d6b7c;
      --border: #d9e2ec;
      --shadow: 0 24px 60px rgba(16, 32, 51, 0.12);
      --primary: #2563eb;
      --primary-hover: #1d4ed8;
      --danger: #dc2626;
      --danger-hover: #b91c1c;
      --ring: #0f62fe;
      --overlay: rgba(15, 23, 42, 0.52);
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 14px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, #e8f0ff 0, transparent 36%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      border: 1px solid var(--border);
      box-shadow: var(--shadow);
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 1000;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--ring);
      outline-offset: 2px;
    }

    .page {
      width: min(1120px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 2rem 0 4rem;
    }

    .hero {
      display: grid;
      gap: 1rem;
      margin-bottom: 1.5rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.05;
      letter-spacing: -0.03em;
    }

    .subtitle {
      margin: 0;
      max-width: 60ch;
      color: var(--muted);
      font-size: 1.02rem;
      line-height: 1.6;
    }

    .workspace {
      display: grid;
      place-items: center;
      padding: 1rem 0 0;
    }

    .card {
      width: min(100%, 760px);
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
      overflow: clip;
    }

    .card__media {
      position: relative;
      background: linear-gradient(180deg, #eaf2ff 0%, #dfe9fb 100%);
      aspect-ratio: 16 / 10;
    }

    .card__media img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .card__body {
      padding: 1.25rem 1.25rem 1.5rem;
      display: grid;
      gap: 1rem;
    }

    .meta {
      display: grid;
      gap: 0.35rem;
    }

    .title-row {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.75rem;
      min-width: 0;
    }

    .card__title {
      margin: 0;
      font-size: 1.15rem;
      line-height: 1.3;
      min-width: 0;
    }

    .pill {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      padding: 0.38rem 0.72rem;
      border-radius: 999px;
      background: var(--surface-2);
      color: var(--muted);
      border: 1px solid var(--border);
      font-size: 0.875rem;
      white-space: nowrap;
    }

    .description {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
    }

    .button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.85rem 1.2rem;
      min-height: 2.75rem;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 0.15s ease, background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:active {
      transform: translateY(0);
    }

    .button:focus-visible {
      outline: 3px solid var(--ring);
      outline-offset: 3px;
    }

    .button--secondary {
      background: var(--surface-2);
      border-color: var(--border);
      color: var(--text);
    }

    .button--secondary:hover {
      background: #eef4fb;
    }

    .button--danger {
      background: var(--danger);
      color: #ffffff;
    }

    .button--danger:hover {
      background: var(--danger-hover);
    }

    .status {
      min-height: 1.5rem;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .empty-state {
      display: none;
      width: min(100%, 760px);
      padding: 2rem;
      border-radius: var(--radius-xl);
      border: 1px solid var(--border);
      background: var(--surface);
      box-shadow: var(--shadow);
      text-align: center;
    }

    .empty-state h2 {
      margin: 0 0 0.5rem;
      font-size: 1.4rem;
    }

    .empty-state p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    dialog {
      width: min(92vw, 480px);
      border: 1px solid var(--border);
      border-radius: 24px;
      padding: 0;
      box-shadow: var(--shadow);
      color: var(--text);
      background: var(--surface);
    }

    dialog::backdrop {
      background: var(--overlay);
      backdrop-filter: blur(4px);
    }

    .dialog__panel {
      padding: 1.4rem;
      display: grid;
      gap: 1rem;
    }

    .dialog__icon {
      width: 3rem;
      height: 3rem;
      display: grid;
      place-items: center;
      border-radius: 999px;
      background: #fef2f2;
      color: var(--danger);
      font-size: 1.35rem;
      font-weight: 700;
    }

    .dialog__title {
      margin: 0;
      font-size: 1.25rem;
      line-height: 1.25;
    }

    .dialog__text {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog__actions {
      display: flex;
      justify-content: flex-end;
      flex-wrap: wrap;
      gap: 0.75rem;
      padding-top: 0.25rem;
    }

    dialog button {
      min-width: 7.5rem;
    }

    @media (max-width: 640px) {
      .page {
        width: min(100% - 1rem, 1120px);
        padding-top: 1rem;
      }

      .card__body {
        padding: 1rem;
      }

      .dialog__actions {
        justify-content: stretch;
      }

      .dialog__actions .button {
        flex: 1 1 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --shadow: none;
        --primary: ButtonText;
        --primary-hover: ButtonText;
        --danger: ButtonText;
        --danger-hover: ButtonText;
        --ring: Highlight;
        --overlay: rgba(0, 0, 0, 0.6);
      }

      .pill,
      .button--secondary,
      dialog,
      .card,
      .empty-state {
        forced-color-adjust: auto;
      }

      .button--danger {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonBorder;
      }

      .button--secondary {
        background: ButtonFace;
        color: ButtonText;
      }

      .dialog__icon {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main" class="page">
    <section class="hero" aria-labelledby="page-title">
      <h1 id="page-title">Image preview</h1>
      <p class="subtitle">Review a photo before deleting it from your library. The confirmation dialog opens from the delete button below the image.</p>
    </section>

    <section class="workspace" aria-label="Preview">
      <article class="card" id="image-card">
        <div class="card__media">
          <img
            src="https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1600&q=80"
            alt="A desk setup with a laptop, notebook, and coffee beside a window"
          >
        </div>
        <div class="card__body">
          <div class="meta">
            <div class="title-row">
              <h2 class="card__title">Workspace edit 24</h2>
              <span class="pill">4.8 MB</span>
            </div>
            <p class="description">Uploaded today at 3:42 PM. This file is stored in your personal library and can be removed at any time.</p>
          </div>

          <div class="actions">
            <button type="button" class="button button--secondary" aria-label="Download image">Download</button>
            <button type="button" class="button button--danger trigger" id="delete-trigger">Delete image</button>
          </div>

          <p class="status" id="status" aria-live="polite"></p>
        </div>
      </article>

      <div class="empty-state" id="empty-state" tabindex="-1" hidden>
        <h2>Image deleted</h2>
        <p>This image has been removed from your library.</p>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description">
    <div class="dialog__panel">
      <div class="dialog__icon" aria-hidden="true">!</div>
      <div>
        <h2 class="dialog__title" id="delete-title">Delete this image?</h2>
        <p class="dialog__text" id="delete-description">This will permanently remove the image from your library. You won&rsquo;t be able to restore it later.</p>
      </div>
      <div class="dialog__actions">
        <button type="button" class="button button--secondary" id="cancel-button">Cancel</button>
        <button type="button" class="button button--danger" id="confirm-button">Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const trigger = document.querySelector('.trigger');
    const cancelButton = document.getElementById('cancel-button');
    const confirmButton = document.getElementById('confirm-button');
    const imageCard = document.getElementById('image-card');
    const emptyState = document.getElementById('empty-state');
    const status = document.getElementById('status');

    let focusTarget = trigger;

    trigger.addEventListener('click', () => {
      focusTarget = trigger;
      dialog.showModal();
      cancelButton.focus();
    });

    cancelButton.addEventListener('click', () => {
      dialog.close('cancel');
    });

    confirmButton.addEventListener('click', () => {
      focusTarget = emptyState;
      dialog.close('confirm');
      imageCard.hidden = true;
      emptyState.hidden = false;
      status.textContent = 'Image deleted from your library.';
    });

    dialog.addEventListener('close', () => {
      if (focusTarget instanceof HTMLElement) {
        focusTarget.focus();
      } else {
        trigger.focus();
      }
    });

    dialog.addEventListener('cancel', (event) => {
      event.preventDefault();
      dialog.close('cancel');
    });

    dialog.addEventListener('click', (event) => {
      if (event.target === dialog) {
        dialog.close('backdrop');
      }
    });
  </script>
</body>
</html>
